@torch.jit.script
def _candidate_normalized_gru_scan(
    input_gates: torch.Tensor,
    hidden: torch.Tensor,
    weight_hh: torch.Tensor,
    bias_hh: torch.Tensor,
    norm_weight: torch.Tensor,
    norm_bias: torch.Tensor,
    eps: float,
) -> tuple[torch.Tensor, torch.Tensor]:
    outputs = torch.jit.annotate(list[torch.Tensor], [])
    for step in range(input_gates.size(0)):
        recurrent_gates = torch.nn.functional.linear(hidden, weight_hh, bias_hh)
        input_reset, input_update, input_candidate = input_gates[step].chunk(3, dim=-1)
        hidden_reset, hidden_update, hidden_candidate = recurrent_gates.chunk(3, dim=-1)
        reset = torch.sigmoid(input_reset + hidden_reset)
        update = torch.sigmoid(input_update + hidden_update)
        candidate_preactivation = input_candidate + reset * hidden_candidate
        candidate = torch.tanh(torch.nn.functional.layer_norm(
            candidate_preactivation, [hidden.size(-1)], norm_weight, norm_bias, eps
        ))
        hidden = candidate + update * (hidden - candidate)
        outputs.append(hidden)
    return torch.stack(outputs, dim=0), hidden


class CandidateNormalizedGRU(nn.GRU):
    def __init__(self, input_size: int, hidden_size: int, num_layers: int = 1,
                 batch_first: bool = True, dropout: float = 0.0):
        super().__init__(input_size, hidden_size, num_layers=num_layers,
                         batch_first=batch_first, dropout=dropout)
        self.candidate_norms = nn.ModuleList([
            nn.LayerNorm(hidden_size) for _ in range(num_layers)
        ])

    def forward(self, inputs: torch.Tensor, hx: torch.Tensor | None = None):
        layer_input = inputs.transpose(0, 1) if self.batch_first else inputs
        final_states = []
        for layer, norm in enumerate(self.candidate_norms):
            hidden = (layer_input.new_zeros(layer_input.size(1), self.hidden_size)
                      if hx is None else hx[layer])
            input_gates = torch.nn.functional.linear(
                layer_input, getattr(self, f"weight_ih_l{layer}"),
                getattr(self, f"bias_ih_l{layer}")
            )
            layer_input, hidden = _candidate_normalized_gru_scan(
                input_gates, hidden, getattr(self, f"weight_hh_l{layer}"),
                getattr(self, f"bias_hh_l{layer}"), norm.weight, norm.bias, norm.eps
            )
            final_states.append(hidden)
            if layer + 1 < self.num_layers and self.dropout > 0.0:
                layer_input = torch.nn.functional.dropout(
                    layer_input, p=self.dropout, training=self.training
                )
        output = layer_input.transpose(0, 1) if self.batch_first else layer_input
        return output, torch.stack(final_states, dim=0)


